// src/shared/routes/routes.js
import React, { lazy } from 'react';

const HomePage = lazy(() => import('../../features/Landing/pages/HomePage'));
const LoginPage = lazy(() => import('../../features/Auth/pages/LoginPage'));
const SignUpPage = lazy(() => import('../../features/Auth/pages/SignUpPage'));
const NotFoundPage = lazy(() => import('../../features/Error/pages/NotFoundPage'));
const ExpenseTracker = lazy(() => import('../../features/Finance/components/ExpenseTracker/ExpenseTracker'));
const ProfilePage = lazy(() => import('../../features/User/Profile/ProfilePage'));
const Dashboard = lazy(() => import('../../features/Finance/components/ExpenseTracker/ExpenseTracker'));
const CoursesPage = lazy(() => import('../../features/Education/pages/CoursesPage'));
const CourseDetailPage = lazy(() => import('../../features/Education/pages/CourseDetailPage'));
const ProgressPage = lazy(() => import('../../features/Education/pages/ProgressPage'));
const GardenPage = lazy(() => import('../../features/Education/pages/GardenPage'));
const ChatPage = lazy(() => import('../../features/IA/ChatIA/ChatIAPage'));
const SalesPage = lazy(() => import('../../features/Sales/pages/SalesPage'));
const SalesDashboard = lazy(() => import('../../features/Sales/pages/SalesDashboard'));
const SalesManagement = lazy(() => import('../../features/Sales/pages/SalesManagement'));
const PurchasesManagement = lazy(() => import('../../features/Sales/pages/PurchasesManagement'));
const InventoryManagement = lazy(() => import('../../features/Sales/pages/InventoryManagement'));
const CashFlowManagement = lazy(() => import('../../features/Sales/pages/CashFlowManagement'));
const AccountingManagement = lazy(() => import('../../features/Sales/pages/AccountingManagement'));
const RecoveryPlanner = lazy(() => import('../../features/IA/RecoveryPlanner/RecoveryPlanner'));

const routes = [
  {
    path: '/',
    element: <HomePage />,
  },
  {
    path: '/login',
    element: <LoginPage />,
  },
  {
    path: '/signup',
    element: <SignUpPage />,
  },
  {
    path: '/dashboard',
    element: <Dashboard />,
    protected: true, // Indicar que requiere autenticación
  },
  {
    path: '/expense-tracker',
    element: <ExpenseTracker />,
    protected: true,
  },
  {
    path: '/profile',
    element: <ProfilePage />,
    protected: true,
  },
  {
    path: '/chat-ia',
    element: <ChatPage />,
    protected: true,
  },
  {
    path: '/education/courses',
    element: <CoursesPage />,
    protected: true,
  },
  {
    path: '/education/courses/:courseId',
    element: <CourseDetailPage />,
    protected: true,
  },
  {
    path: '/education/progress',
    element: <ProgressPage />,
    protected: true,
  },
  {
    path: '/education/garden',
    element: <GardenPage />,
    protected: true,
  },
  {
    path: '/ventas',
    element: <SalesPage />,
    protected: true,
  },
  {
    path: '/ventasda',
    component: SalesDashboard,
    exact: true,
    requiresAuth: true
  },
  {
    path: '/ventas/ventas',
    component: SalesManagement,
    exact: true,
    requiresAuth: true
  },
  {
    path: '/ventas/compras',
    component: PurchasesManagement,
    exact: true,
    requiresAuth: true
  },
  {
    path: '/ventas/inventario',
    component: InventoryManagement,
    exact: true,
    requiresAuth: true
  },
  {
    path: '/ventas/flujo-caja',
    component: CashFlowManagement,
    exact: true,
    requiresAuth: true
  },
  {
    path: '/ventas/contabilidad',
    component: AccountingManagement,
    exact: true,
    requiresAuth: true
  },
  {
    path: '/recovery-planner',
    element: <RecoveryPlanner />,
    protected: true,
  },
  {
    path: '/not-found',
    element: <NotFoundPage />,
  },
];

export default routes;